const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const SWORD_BASE_PREMIUM = 100;

const basePremiumOf = (item: Item): number => SWORD_BASE_PREMIUM;

const quotePremium = (items: Item[]): number => {
  const basePremium = sum(items.map(basePremiumOf));

  return (
    basePremium * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE
  );
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => ({
    premium: quotePremium(step.items),
  })),
});

const SWORD_BASE_PREMIUM = 100;

const sum = (amounts: number[]): number =>
  amounts.reduce((total, amount) => total + amount, 0);

const basePremiumOf = (_item: Item): number => SWORD_BASE_PREMIUM;

